import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import Button from 'flarum/common/components/Button';
import SelectDropdown from 'flarum/common/components/SelectDropdown';
import ItemList from 'flarum/common/utils/ItemList';
import listItems from 'flarum/common/helpers/listItems';
import extractText from 'flarum/common/utils/extractText';
import PollList from './Poll/PollList';
import PollListState from '../states/PollListState';
import PollPageHero from './PollPageHero';
import PollsIndexSidebar from './PollsIndexSidebar';
const STATUS_FILTER_VALUE = {
  all: 'any',
  published: '0',
  draft: '1'
};
const STATUSES = ['all', 'published', 'draft'];

// So that /polls/all?filter[isDraft]=1 reads "Drafts", not "All".
function statusFromUrl() {
  const raw = new URLSearchParams(window.location.search).get('filter[isDraft]');
  if (raw === '1' || raw === 'true') return 'draft';
  if (raw === '0' || raw === 'false') return 'published';
  return 'all';
}
export default class PollsPage extends Page {
  status = 'all';
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.forum.attribute('globalPollsEnabled')) {
      m.route.set('/');
      return;
    }
    this.bodyClass = 'App--polls';
    this.status = statusFromUrl();
    this.state = new PollListState({
      // The setting stores an API sort value; the list state works in keys.
      sort: PollListState.sortKey(String(app.forum.attribute('pollsDirectoryDefaultSort') || '')),
      filter: {
        isDraft: STATUS_FILTER_VALUE[this.status]
      }
    });
    this.state.refresh();
    app.setTitle(extractText(app.translator.trans('fof-polls.forum.page.nav')));
  }
  view() {
    if (!this.state) return null;
    return m(PageStructure, {
      className: "PollsPage",
      hero: this.hero.bind(this),
      sidebar: this.sidebar.bind(this)
    }, this.contentItems().toArray());
  }
  hero() {
    return m(PollPageHero, null);
  }
  sidebar() {
    return m(PollsIndexSidebar, null);
  }
  contentItems() {
    const items = new ItemList();
    items.add('toolbar', m("div", {
      className: "IndexPage-toolbar"
    }, this.toolbarItems().toArray()), 100);
    items.add('pollList', m(PollList, {
      state: this.state
    }), 10);
    return items;
  }
  toolbarItems() {
    const items = new ItemList();
    items.add('view', m("ul", {
      className: "IndexPage-toolbar-view"
    }, listItems(this.viewItems().toArray())), 100);
    items.add('action', m("ul", {
      className: "IndexPage-toolbar-action"
    }, listItems(this.actionItems().toArray())), 10);
    return items;
  }
  viewItems() {
    const items = new ItemList();
    items.add('status', m(SelectDropdown, {
      buttonClassName: "Button",
      defaultLabel: app.translator.trans('fof-polls.forum.polls_list.status_filter.all')
    }, STATUSES.map(status => m(Button, {
      active: this.status === status,
      onclick: () => this.setStatus(status)
    }, app.translator.trans(`fof-polls.forum.polls_list.status_filter.${status}`)))), 10);
    const sortMap = this.state.sortMap();
    const currentSort = this.state.getSort();
    items.add('sort', m(SelectDropdown, {
      buttonClassName: "Button",
      defaultLabel: app.translator.trans('fof-polls.forum.polls_list.sort_dropdown.newest')
    }, Object.keys(sortMap).map(key => m(Button, {
      active: currentSort === key,
      onclick: () => this.state.changeSort(key)
    }, app.translator.trans(`fof-polls.forum.polls_list.sort_dropdown.${key}`)))), 0);
    return items;
  }
  actionItems() {
    const items = new ItemList();
    items.add('refresh', m(Button, {
      className: "Button Button--icon",
      icon: "fas fa-sync",
      "aria-label": extractText(app.translator.trans('core.forum.index.refresh_tooltip')),
      onclick: () => this.state.refresh()
    }));
    return items;
  }
  setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    const params = this.state.getParams();
    this.state.refreshParams({
      ...params,
      filter: {
        ...(params.filter || {}),
        isDraft: STATUS_FILTER_VALUE[status]
      }
    }, 1);
  }
}
flarum.reg.add('fof-polls', 'forum/components/PollsPage', PollsPage);