import app from 'flarum/forum/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import FormGroup from 'flarum/common/components/FormGroup';
import Stream from 'flarum/common/utils/Stream';
import dayjs from 'dayjs';
import utc from 'dayjs/plugin/utc';
dayjs.extend(utc);
export default class SchedulePollModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);

    // The model returns UTC; datetime-local wants the local-zone equivalent.
    const scheduled = this.attrs.poll.scheduledPublishAt();
    this.datetime = Stream(scheduled ? dayjs(scheduled).local().format('YYYY-MM-DDTHH:mm') : '');
  }
  className() {
    return 'SchedulePollModal Modal--small';
  }
  title() {
    return app.translator.trans(this.attrs.poll.scheduledPublishAt() ? 'fof-polls.forum.compose.schedule_publication_edit' : 'fof-polls.forum.compose.schedule_publication');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(FormGroup, {
      type: "datetime-local",
      name: "scheduledFor",
      label: app.translator.trans('fof-polls.forum.compose.schedule_datetime_label'),
      required: true,
      stream: this.datetime
    }), m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading
    }, app.translator.trans('fof-polls.forum.compose.schedule_submit'))));
  }
  async onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.alertAttrs = null;
    try {
      // Persist the form's edits first, so we never schedule stale data.
      if (this.attrs.form && !(await this.attrs.form.submit({
        isDraft: true
      }))) {
        return;
      }
      const poll = this.attrs.form ? this.attrs.form.state.poll : this.attrs.poll;
      if (!poll.id()) {
        throw new Error('Cannot schedule an unsaved poll.');
      }
      await poll.publish({
        scheduledFor: new Date(this.datetime()).toISOString()
      }, this.onerror.bind(this));
      this.hide();
      this.attrs.onSuccess?.(poll);
    } catch (error) {
      if (!this.alertAttrs) {
        this.alertAttrs = {
          type: 'error',
          content: error?.message ?? app.translator.trans('core.lib.error.generic_message')
        };
      }
    } finally {
      this.loading = false;
      m.redraw();
    }
  }
}
flarum.reg.add('fof-polls', 'forum/components/SchedulePollModal', SchedulePollModal);