import app from 'flarum/forum/app';
import Button from 'flarum/common/components/Button';
import Separator from 'flarum/common/components/Separator';
import ItemList from 'flarum/common/utils/ItemList';
import extractText from 'flarum/common/utils/extractText';
import ComposePollPage from '../components/ComposePollPage';
import PollsPage from '../components/PollsPage';
import PollViewPage from '../components/PollViewPage';
import PollListState from '../states/PollListState';
import SchedulePollModal from '../components/SchedulePollModal';
export default {
  controls(poll, context) {
    const items = new ItemList();
    const sections = ['poll', 'moderation', 'destructive'];
    sections.forEach(section => {
      const controls = this[`${section}Controls`](poll, context).toArray();
      if (!controls.length) return;
      controls.forEach(item => items.add(item.itemName, item));
      items.add(`${section}Separator`, m(Separator, null));
    });
    return items;
  },
  pollControls(poll, context) {
    return new ItemList();
  },
  moderationControls(poll, context) {
    const items = new ItemList();
    if (poll.canEdit()) {
      items.add('edit', m(Button, {
        icon: "fas fa-pencil-alt",
        onclick: this.editAction.bind(this, poll)
      }, app.translator.trans('fof-polls.forum.poll_controls.edit_label')));
    }
    if (poll.canPublish() && poll.isDraft()) {
      items.add('publish', m(Button, {
        icon: "fas fa-paper-plane",
        onclick: () => this.publishAction(poll)
      }, app.translator.trans('fof-polls.forum.poll_controls.publish_label')));
      items.add('schedulePublish', m(Button, {
        icon: "fas fa-clock",
        onclick: () => this.scheduleAction(poll)
      }, app.translator.trans(poll.isScheduled() ? 'fof-polls.forum.poll_controls.edit_schedule_publish_label' : 'fof-polls.forum.poll_controls.schedule_publish_label')));
      if (poll.isScheduled()) {
        items.add('cancelSchedule', m(Button, {
          icon: "fas fa-times",
          onclick: () => this.cancelScheduleAction(poll)
        }, app.translator.trans('fof-polls.forum.poll_controls.cancel_schedule_label')));
      }
    }
    return items;
  },
  destructiveControls(poll, context) {
    const items = new ItemList();
    if (poll.canUnpublish()) {
      items.add('unpublish', m(Button, {
        icon: "fas fa-undo",
        onclick: () => this.unpublishAction(poll)
      }, app.translator.trans('fof-polls.forum.poll_controls.unpublish_label')));
    }
    if (poll.canDelete()) {
      items.add('delete', m(Button, {
        icon: "far fa-trash-alt",
        onclick: this.deleteAction.bind(this, poll)
      }, app.translator.trans('fof-polls.forum.poll_controls.delete_label')));
    }
    return items;
  },
  editAction(poll) {
    m.route.set(app.route('fof.polls.composer', {
      id: poll.id()
    }));
  },
  scheduleAction(poll) {
    app.modal.show(SchedulePollModal, {
      poll,
      form: null,
      onSuccess: app.current.matches(PollsPage) ? () => m.redraw() : () => m.route.set(app.route('fof.polls.view', {
        id: poll.id()
      }))
    });
  },
  async deleteAction(poll) {
    if (!confirm(extractText(app.translator.trans('fof-polls.forum.poll_controls.delete_confirmation')))) {
      return;
    }
    return poll.delete().then(() => {
      this.alert('success', 'fof-polls.forum.poll_controls.delete_success_message');
      if (app.current.matches(ComposePollPage) || app.current.matches(PollViewPage)) {
        m.route.set(app.route('fof.polls.list'));
      } else {
        PollListState.notifyDeleted(poll);
      }
    }).catch(() => this.alert('error', 'fof-polls.forum.poll_controls.delete_error_message'));
  },
  async publishAction(poll) {
    try {
      await poll.publish({}, error => this.errorAlert(error));
      this.alert('success', 'fof-polls.forum.poll_controls.publish_success');
      m.redraw();
    } catch {
      // errorAlert already reported it.
    }
  },
  async cancelScheduleAction(poll) {
    try {
      await poll.publish({
        scheduledFor: null
      }, error => this.errorAlert(error));
      this.alert('success', 'fof-polls.forum.poll_controls.cancel_schedule_success');
      m.redraw();
    } catch {
      // errorAlert already reported it.
    }
  },
  async unpublishAction(poll) {
    if (!confirm(extractText(app.translator.trans('fof-polls.forum.poll_controls.unpublish_confirmation')))) return;
    try {
      await poll.unpublish(() => app.alerts.show({
        type: 'error'
      }, app.translator.trans('fof-polls.forum.poll_controls.unpublish_error_has_votes')));
      this.alert('success', 'fof-polls.forum.poll_controls.unpublish_success');
      m.redraw();
    } catch {
      // The error handler above already reported it.
    }
  },
  alert(type, key) {
    const id = app.alerts.show({
      type
    }, app.translator.trans(key));
    if (type === 'success') setTimeout(() => app.alerts.dismiss(id), 10000);
  },
  errorAlert(error) {
    const detail = error?.response?.errors?.[0]?.detail;
    app.alerts.show({
      type: 'error'
    }, detail ?? app.translator.trans('fof-polls.forum.poll_form.error'));
  }
};