import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import ItemList from 'flarum/common/utils/ItemList';
import PollGroupListItem from './PollGroup/PollGroupListItem';
import PollPageHero from './PollPageHero';
import PollsIndexSidebar from './PollsIndexSidebar';
export default class PollGroupViewPage extends Page {
  loading = false;
  pollGroup = null;
  oninit(vnode) {
    super.oninit(vnode);
    if (!app.forum.attribute('canViewPollGroups')) {
      m.route.set('/');
      return;
    }
    this.bodyClass = 'App--polls';
    const id = m.route.param('id');
    const cached = app.store.getById('poll_groups', id);

    // The listing loads a group's polls without their options.
    if (cached && (cached.polls() ?? []).every(poll => poll?.options().length)) {
      this.pollGroup = cached;
      app.setTitle(cached.name());
    } else {
      this.loading = true;
    }
    app.store.find('poll_groups', id).then(pollGroup => {
      this.pollGroup = pollGroup;
      this.loading = false;
      app.setTitle(pollGroup.name());
      m.redraw();
    });
  }
  view() {
    return m(PageStructure, {
      className: "PollGroupViewPage",
      hero: this.hero.bind(this),
      sidebar: this.sidebar.bind(this),
      loading: this.loading
    }, this.contentItems().toArray());
  }
  hero() {
    return m(PollPageHero, {
      title: this.pollGroup?.name(),
      icon: "fas fa-layer-group"
    });
  }
  sidebar() {
    return m(PollsIndexSidebar, null);
  }
  contentItems() {
    const items = new ItemList();
    if (this.pollGroup) {
      items.add('pollGroup', m(PollGroupListItem, {
        pollGroup: this.pollGroup
      }));
    }
    return items;
  }
}
flarum.reg.add('fof-polls', 'forum/components/PollGroupViewPage', PollGroupViewPage);